"""SCMOVS update: the initial password of a NEW user is created automatically and emailed to them.

  * Add New User and Add Student: the form no longer asks for a password. The server creates a random one
    (12+ characters, letters and numbers), stores only its hash, and emails it to the new user's address
    (their @gmail.com or @holycross.edu.ph address) with their username and a sign-in link.
  * The user must choose a new password the first time they sign in (as before).
  * The audit log records THAT the email was sent (to a masked address), never the password.
  * If the email cannot be sent (SMTP not set up, or Gmail refuses), the account is still created and the password is
    shown ONCE to the admin with a clear warning, so the user is never locked out.

This needs working email: the MAIL_* and PUBLIC_BASE_URL settings in your .env (the same ones Forgot Password uses).
NO database change is needed.

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_welcome_email_update.py
  3. Restart the app (python run.py).

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/accounts.py': "",
    'app/admin/routes.py': "",
    'app/mail_templates.py': "",
    'app/students/routes.py': "",
    'templates/students/_password_result.html': "",
    'templates/super_admin/users/_form_modal.html': "",
    'tests/run_all.sh': "",
    'tests/test_email_domains.py': "",
    'tests/test_initial_password_email.py': "",
    'tests/test_new_features.py': "",
    'tests/test_status_icons.py': "",
    'tests/test_users.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    if not os.path.isfile(os.path.join(ROOT, "app", "locations.py")):
        print("STOP: this update builds on the previous ones. Apply apply_big_update.py first (and apply_autostart_update.py).")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print("\nDone. Restart the app (python run.py).")
    print("Remember: the .env needs MAIL_SERVER, MAIL_USERNAME, MAIL_PASSWORD (a Gmail App Password), MAIL_SENDER and PUBLIC_BASE_URL.")


if __name__ == "__main__":
    main()
